// Converts the web's film-emulation GLSL (app/lib/filmShaderChunk.ts) to WGSL
// for the Mac app's engine, so both renderers share one definition of every
// film look. `pnpm gen:film-wgsl` writes crates/etch-core/src/film.wgsl;
// tests/unit/filmWgsl.test.ts fails if that file is out of date.

const HEADER = `// GENERATED by scripts/gen-film-wgsl.mjs from app/lib/filmShaderChunk.ts.
// Do not edit; change the GLSL and regenerate.
`;

/** Converts the film chunk's GLSL (a fixed set of statement shapes) to WGSL. */
export function convertFilmChunk(glsl) {
  const lines = glsl.split("\n").map((line) => {
    let out = line;
    out = out.replace(/^(\s*)vec3 applyFilmChunk_(\d+)\(vec3 color, int filmType, float strength\) \{/, "$1fn apply_film_chunk_$2(color: vec3<f32>, filmType: i32, strength: f32) -> vec3<f32> {");
    out = out.replace(/^(\s*)vec3 applyFilmEmulation\(vec3 color, int filmType, float strength\) \{/, "$1fn apply_film_emulation(color: vec3<f32>, filmType: i32, strength: f32) -> vec3<f32> {");
    out = out.replace(/applyFilmChunk_(\d+)\(/g, "apply_film_chunk_$1(");
    out = out.replace(/^(\s*)if \((.+?)\) return (.+);\s*$/, "$1if ($2) { return $3; }");
    out = out.replace(/^(\s*)vec3 (\w+) = (.+);/, "$1var $2: vec3<f32> = $3;");
    out = out.replace(/^(\s*)float (\w+) = (.+);/, "$1let $2: f32 = $3;");
    // GLSL lets scalars stand in for vectors; WGSL doesn't.
    out = out.replace(/smoothstep\(([^,()]+), ([^,()]+), filmColor\)/g, "film_smoothstep3($1, $2, filmColor)");
    out = out.replace(/smoothstep\(/g, "film_smoothstep(");
    out = out.replace(/clamp\(filmColor, ([^,()]+), ([^,()]+)\)/g, "clamp(filmColor, vec3<f32>($1), vec3<f32>($2))");
    out = out.replace(/\bvec3\(/g, "vec3<f32>(");
    out = out.replace(/\bgetLuma\(/g, "film_luma(");
    out = out.replace(/\brgb2hsl\(/g, "rgb_to_hsl(");
    out = out.replace(/\bhsl2rgb\(/g, "hsl_to_rgb(");
    return out.replace(/\s+$/, "");
  });
  const wgsl = lines.join("\n").trim();
  const leftover = wgsl.match(/\b(float|int|vec3 \w+|getLuma|rgb2hsl|hsl2rgb)\b(?!<)/);
  if (leftover) throw new Error(`Unconverted GLSL in the film chunk: "${leftover[0]}". Teach scripts/lib/filmWgsl.mjs this shape.`);
  return `${HEADER}\n${wgsl}\n`;
}

/** Film ids in shader-index order, from app/lib/filmEmulations.ts source. */
export function filmIds(source) {
  return [...source.matchAll(/^\s+id: "([a-z0-9_]+)", name:/gm)].map((match) => match[1]);
}
